using Dip.Application.Features.Projects; using Microsoft.AspNetCore.Mvc; namespace Dip.Api.Controllers; [ApiController][Route("api/projects")] public sealed class ProjectsController:ControllerBase{private readonly ProjectService _s;public ProjectsController(ProjectService s)=>_s=s;[HttpGet]public Task<IReadOnlyList<ProjectDto>>List(CancellationToken ct)=>_s.ListAsync(ct);[HttpGet("{id:guid}")]public async Task<ActionResult<ProjectDto>>Get(Guid id,CancellationToken ct){var p=await _s.GetAsync(id,ct);return p is null?NotFound():Ok(p);}[HttpPost]public async Task<ActionResult<ProjectDto>>Create(CreateProjectCommand c,CancellationToken ct){var p=await _s.CreateAsync(c,ct);return CreatedAtAction(nameof(Get),new{id=p.Id},p);}}